"""Narrative rewrite for Japanese, Roman, Chinese, Mesoamerican starter packs.
Keeps existing titles (already good); rewrites cards + quiz to story-first."""
import json, io, glob

REVIEW = {"status": "reviewed", "reviewedBy": "Devin (AI editorial review)", "reviewedAt": "2026-11-24",
          "reviewType": "editorial",
          "notes": "AI editorial review by Devin on 2026-11-24: narrative-first rewrite; cards retell the story, verbatim source excerpts preserved. This is not independent scholarly review or scholarly certification; specialist and community review remains recommended."}

def C(i, t, b, r, o, k="story"):
    return {"id": f"card-{i:02d}", "kind": k, "title": t, "body": b,
            "sourceRefIds": r, "objectiveIds": [o]}

def Q(qid, prompt, right, wrongs, expl, r, o):
    return {"id": qid, "type": "single-choice", "prompt": prompt,
            "choices": [{"id": "a", "text": right}] + [{"id": c, "text": t} for c, t in zip("bcd", wrongs)],
            "answerId": "a", "explanation": expl, "sourceRefIds": r, "objectiveIds": [o]}

def W(trad, pat, tags, objs, cards, quiz):
    f = glob.glob(f'content/lessons/{trad}/**/*{pat}*.json', recursive=True)[0]
    d = json.load(io.open(f, encoding='utf-8'))
    d.update(version=d.get('version', 1) + 1, estimatedMinutes=3,
             tags=tags, learningObjectives=objs, narrativeBlocks=cards, quiz=quiz, review=dict(REVIEW))
    json.dump(d, io.open(f, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)

# ===== JAPANESE =====
W('japanese', 'day-01-creation', ["izanagi", "izanami", "creation", "japanese"],
  [{"id": "obj.iz.creation", "text": "How do Izanagi and Izanami create the islands?"},
   {"id": "obj.iz.flaw", "text": "What goes wrong at their wedding?"}],
  [C(1, "The spear and the brine", "The elder gods send Izanagi and Izanami down from the Floating Bridge of Heaven. They thrust the jeweled spear into the ocean brine and lift it — and the drops falling from its point become Onogoro, the first island.", ["main"], "obj.iz.creation"),
   C(2, "The wedding around the pillar", "On Onogoro they build the heavenly pillar and marry by circling it — but Izanami greets her husband first, a breach of order. Their firstborn is the deformed Hiruko, the leech-child, set adrift in a boat of reeds.", ["main"], "obj.iz.flaw"),
   C(3, "A second rite, a better birth", "They redo the wedding properly — the man speaking first — and this time the union succeeds: from their embrace are born the islands of Japan itself, then the kami of wind, trees, mountains, and seas.", ["main"], "obj.iz.creation"),
   C(4, "The birth that burns", "Then Izanami bears the fire god, and it kills her. The creation that began with drops of brine ends at death's door — and Izanagi's grief will take him into the underworld later this week.", ["main"], "obj.iz.flaw"),
   C(5, "Gods who live close", "In Shinto, the kami are not remote: the land itself is born of gods, and gods marry, err, grieve, and die. That closeness shapes every story this week.", ["main"], "obj.iz.creation", "context")],
  [Q("q1", "What do the drops from the jeweled spear become?",
     "Onogoro — the first island, where Izanagi and Izanami begin creation",
     ["The sea-serpent Orochi", "The Heavenly Rock Dwelling", "The islands of Japan directly"],
     "The spear-drops make Onogoro — the platform for everything after.", ["main"], "obj.iz.creation"),
   Q("q2", "Why is the first child, Hiruko, deformed?",
     "Because Izanami spoke first at the pillar wedding — a breach of the rite's order",
     ["The gods cursed the union", "The fire god burned him in the womb", "He was born in the underworld"],
     "The flawed rite produces the flawed child — ritual order matters.", ["main"], "obj.iz.flaw")])

W('japanese', 'day-02-amaterasu', ["amaterasu", "susanoo", "cave", "japanese"],
  [{"id": "obj.ama.rampage", "text": "What does Susanoo do to Amaterasu?"},
   {"id": "obj.ama.return", "text": "How is the sun brought back?"}],
  [C(1, "The storm god's rampage", "Susanoo, ordered to rule the sea, instead storms up to his sister Amaterasu's realm: he wrecks her rice paddies, fouls her hall, and in the worst outrage takes a heavenly piebald horse and, flaying it with a backward flaying, hurls its carcass through her weaving-hall roof.", ["offense"], "obj.ama.rampage"),
   C(2, "The sun shuts herself away", "A weaving-maiden is struck dead; Amaterasu, appalled, retreats into the Heavenly Rock Dwelling and seals it with a boulder. The world goes dark — and in the darkness all manner of calamity stirs.", ["cave"], "obj.ama.rampage"),
   C(3, "The noisiest plan ever hatched", "Eight hundred myriads of gods gather at the cave mouth. Their plan is not force but theatre: they hang a mirror and jewels in a tree, roosters crow, and the goddess Uzume dances a wild, scandalous dance — the gods roar with laughter.", ["festival"], "obj.ama.return"),
   C(4, "Curiosity opens the door", "Amaterasu peeks out: what could be funnier than her light? The mirror shows her own radiance — and while she stares, a god pulls her out and a sacred rope seals the cave behind her. Light returns to the world.", ["festival"], "obj.ama.return"),
   C(5, "A festival that worked", "This is why Japanese matsuri are noisy and communal: the myth says the way back from darkness is shared joy, not power. The gods' racket is the world's first festival.", ["cave", "festival"], "obj.ama.return", "context")],
  [Q("q1", "Why does the world go dark?",
     "Amaterasu hides in the Heavenly Rock Dwelling after Susanoo's outrages — the sun itself withdraws",
     ["The storm god devours the sun", "A flood extinguishes the sky-fires", "The moon blocks the sun in vengeance"],
     "The darkness is her grief and shock — not an attack on the sun but its withdrawal.",
     ["offense", "cave"], "obj.ama.rampage"),
   Q("q2", "How do the gods bring her back?",
     "Uzume's wild dance makes the gods laugh; Amaterasu's curiosity — and her own reflection — draws her out",
     ["They bribe her with new lands", "They break the boulder open", "They threaten Susanoo's life"],
     "The sun returns through laughter and curiosity — the world's first festival.",
     ["festival"], "obj.ama.return")])

W('japanese', 'day-03-susanoo', ["susanoo", "orochi", "kusanagi", "japanese"],
  [{"id": "obj.sus.serpent", "text": "How does Susanoo defeat Yamata no Orochi?"},
   {"id": "obj.sus.sword", "text": "What does he find inside the serpent?"}],
  [C(1, "Exile in Izumo", "Cast out of heaven for the rampage against Amaterasu, Susanoo descends to Izumo province — a disgraced storm god looking for somewhere to belong.", ["disruption"], "obj.sus.serpent"),
   C(2, "The weeping elders", "By a river he finds an old couple weeping over their last daughter: each year the eight-headed serpent Yamata no Orochi comes and devours one of their girls — seven daughters are already gone.", ["disruption"], "obj.sus.serpent"),
   C(3, "Sake for eight heads", "Susanoo's plan is simple and mythic: he turns the girl into a comb in his hair, then builds a fence with eight gates — behind each, a vat of strong sake. The serpent drinks all eight vats dry and sleeps.", ["disruption"], "obj.sus.serpent"),
   C(4, "The sword in the tail", "He cuts the monster apart — and in its middle tail his blade chips on hidden steel: the sword Kusanagi, which he sends to Amaterasu in reconciliation, and which becomes one of Japan's three imperial regalia.", ["withdrawal"], "obj.sus.sword"),
   C(5, "The storm god's other face", "The same force that wrecked heaven becomes Izumo's protector. Japanese myth lets its disruptors be redeemed by the very wildness that condemned them.", ["disruption", "withdrawal"], "obj.sus.serpent", "context")],
  [Q("q1", "How does Susanoo defeat Yamata no Orochi?",
     "He sets out eight vats of sake — the serpent drinks and sleeps, and he cuts it apart",
     ["He calls down a lightning strike", "He poisons the river it drinks from", "He binds it with the gods' rope"],
     "Cunning, not force: the sake-vats do what no sword could.", ["disruption"], "obj.sus.serpent"),
   Q("q2", "What does Susanoo find inside the serpent's tail?",
     "The sword Kusanagi — given to Amaterasu, later one of the three imperial regalia",
     ["A second sleeping serpent", "The stolen daughters alive", "Amaterasu's lost mirror"],
     "The Kusanagi sword — the regalia that reaches Japanese emperors.", ["withdrawal"], "obj.sus.sword")])

W('japanese', 'day-04-kami-boundaries', ["urashima", "folktale", "time", "japanese"],
  [{"id": "obj.ura.voyage", "text": "Where does the turtle take Urashima?"},
   {"id": "obj.ura.box", "text": "What does opening the box do?"}],
  [C(1, "The boy who saved a turtle", "The fisherman Urashima Taro rescues a turtle from boys tormenting it on the beach. Days later the turtle returns and offers to carry him under the sea to the Dragon King's palace.", ["warning"], "obj.ura.voyage"),
   C(2, "Three years that feel like days", "In the palace he is feasted by the princess Otohime — dances, wonders, days that slip by like hours. Three years pass without his noticing: enchanted places run on a different clock.", ["warning"], "obj.ura.voyage"),
   C(3, "The forbidden box", "When homesickness finally wins, Otohime lets him go with a parting gift: a jeweled box he must NEVER open. Every wonderland has its one rule.", ["warning"], "obj.ura.box"),
   C(4, "Three hundred years late", "He lands and knows no one. In the village records a stranger reads him an old entry: Urashima Taro went to sea three hundred years ago and never returned. He opens the box — white smoke rises, his stolen centuries, and he becomes an old man on the shore.", ["return"], "obj.ura.box"),
   C(5, "A folktale, not a myth of gods", "Unlike this week's Kojiki stories, Urashima is a Japanese folktale — a village story about time, wonder, and the cost of leaving home. Different shelf, same questions.", ["warning", "return"], "obj.ura.box", "flavor")],
  [Q("q1", "What does Urashima find when he returns home?",
     "Centuries have passed — his name is in the village records as a man lost at sea three hundred years ago",
     ["His village has become a city", "Otohime is waiting on the shore", "The turtle has aged into a dragon"],
     "Time ran differently under the sea — three years down, three hundred up.",
     ["return"], "obj.ura.voyage"),
   Q("q2", "What happens when he opens the box?",
     "White smoke escapes — his true age — and he becomes an old man on the shore",
     ["A flood drowns the village", "He forgets the palace entirely", "Otohime appears to reclaim him"],
     "The box held his stolen years — opening it lets them catch up.", ["return"], "obj.ura.box")])

W('japanese', 'day-05-izanami-boundary', ["izanami", "yomi", "izanagi", "japanese"],
  [{"id": "obj.yomi.descent", "text": "What happens when Izanagi looks at Izanami?"},
   {"id": "obj.yomi.vow", "text": "What do the two gods vow at the boulder?"}],
  [C(1, "Into the Land of Gloom", "Izanagi cannot accept Izanami's death by fire-birth. He descends to Yomi — the Land of Gloom — to beg her to come back to the world they made together.", ["yomi"], "obj.yomi.descent"),
   C(2, "Wait in the dark", "She agrees to ask the gods of Yomi — but on one condition: he must not look at her. He waits in the darkened hall until patience breaks: he snaps a tooth from his comb, lights it, and looks.", ["yomi"], "obj.yomi.descent"),
   C(3, "The rotting beloved", "Her body is a mass of maggots and thunder-deities. Shamed beyond forgiveness, she sends the hags of Yomi after him — he slows them by throwing his comb, then grapes, then bamboo shoots, and at last blocks the pass of Yomi with a giant boulder.", ["yomi"], "obj.yomi.descent"),
   C(4, "The divorce spoken through stone", "Through the boulder Izanami vows: 'I will strangle a thousand of your people every day.' Izanagi answers: 'Then I will cause fifteen hundred to be born.' The world's rates of death and birth are their divorce settlement.", ["yomi"], "obj.yomi.vow"),
   C(5, "Purification begins here", "Polluted by the land of death, Izanagi washes in a river — and from his washed face are born the week's great gods: Amaterasu from his left eye, Tsukuyomi from his right, Susanoo from his nose. Cleansing makes the gods.", ["yomi"], "obj.yomi.descent", "context")],
  [Q("q1", "What does Izanagi see when he lights his comb-tooth?",
     "Izanami's rotting corpse — a mass of maggots and thunder-deities",
     ["Her spirit already reborn", "The throne of Yomi's king", "Her face unchanged and sleeping"],
     "The look breaks her bargain — and earns her eternal rage.",
     ["yomi"], "obj.yomi.descent"),
   Q("q2", "What do Izanagi and Izanami vow through the boulder?",
     "She will kill a thousand people a day; he will see fifteen hundred born — death and birth as their settlement",
     ["To share rule of Yomi", "To forget each other forever", "To divide the islands between them"],
     "The world's birth-death balance is fixed by their divorce.", ["yomi"], "obj.yomi.vow")])

# ===== ROMAN =====
W('roman', 'day-01-ovid-change', ["ovid", "metamorphoses", "daphne", "roman"],
  [{"id": "obj.ovid.change", "text": "What is the Metamorphoses about?"},
   {"id": "obj.ovid.daphne", "text": "How does Daphne escape Apollo?"}],
  [C(1, "Bodies changed into new forms", "Ovid opens the Metamorphoses with a promise: his poem is of shapes changed into new bodies, spun as one unbroken song from the world's creation down to his own day — nothing stable, everything becoming.", ["proem"], "obj.ovid.change"),
   C(2, "Why change?", "For Ovid, transformation is the world's one constant: pursued nymphs become trees, grieving mothers become stone, beloved boys become flowers, emperors become stars. Every myth is a change of state.", ["proem"], "obj.ovid.change"),
   C(3, "Apollo's first desire", "Fresh from killing the serpent Python, Apollo mocks Cupid's toy bow — and Cupid answers with two arrows: gold for Apollo, so he burns with desire for the nymph Daphne; lead for her, so she recoils from love entirely.", ["daphne"], "obj.ovid.daphne"),
   C(4, "The chase and the laurel", "Apollo hunts her through the woods, listing his glories as he runs — at the river's edge Daphne prays to her father the river-god to destroy her beauty. Bark closes over her legs, leaves crown her hair: she becomes the laurel tree.", ["daphne"], "obj.ovid.daphne"),
   C(5, "The laurel as memorial", "Apollo claims the tree as his own: laurel will crown his lyre, his poets, Rome's victors. Ovid's pattern is set — every transformation is both a loss and a monument.", ["proem", "daphne"], "obj.ovid.daphne", "context")],
  [Q("q1", "What do Cupid's two arrows do?",
     "Gold makes Apollo burn for Daphne; lead makes her recoil from love — engineered pursuit",
     ["Both arrows make them fall in love", "Gold wounds Apollo; lead blinds Daphne", "One kills, the other heals"],
     "Cupid rigs the chase: desire and refusal at once.", ["daphne"], "obj.ovid.daphne"),
   Q("q2", "How does Daphne escape Apollo?",
     "Her father transforms her into a laurel tree at her own prayer — escape through transformation",
     ["She drowns herself in the river", "The gods strike Apollo down", "She outruns him to the sea"],
     "She becomes the laurel — losing her form to keep her freedom.", ["daphne"], "obj.ovid.daphne")])

W('roman', 'day-02-jupiter', ["lycaon", "jupiter", "flood", "roman"],
  [{"id": "obj.lyc.test", "text": "How does Lycaon test Jupiter?"},
   {"id": "obj.lyc.wolf", "text": "What is his punishment?"}],
  [C(1, "The council of the gods", "Jupiter summons the gods to report on humanity: the wickedness has grown unbearable, and he tells them of the test he ran in person on King Lycaon of Arcadia.", ["lycaon"], "obj.lyc.test"),
   C(2, "The feast of human flesh", "Disguised as a mortal, Jupiter visits Lycaon's court. The king, to see whether his guest is truly a god, murders a hostage and serves the flesh at dinner — a crime dressed as an experiment.", ["lycaon"], "obj.lyc.test"),
   C(3, "The lightning answer", "Jupiter's lightning blasts the palace; Lycaon flees howling into the fields — and the howl continues as his body changes: his savagery made literal, he becomes a wolf.", ["lycaon"], "obj.lyc.wolf"),
   C(4, "The case for the flood", "One monster convicted, Jupiter argues the whole species has failed — and the gods agree: the flood that will drown the world is coming. Lycaon is the evidence.", ["lycaon"], "obj.lyc.wolf"),
   C(5, "Ovid's Roman frame", "This flood is not Mesopotamia's whim or the Bible's covenant — in Ovid it is a judgment on a corrupt age, argued before a senate of gods, with the wolf-king as Exhibit A.", ["lycaon"], "obj.lyc.test", "context")],
  [Q("q1", "How does Lycaon test his divine guest?",
     "He murders a hostage and serves the flesh at dinner — crime disguised as experiment",
     ["He challenges Jupiter to a hunt", "He hides the god's thunderbolt", "He refuses the god shelter"],
     "The cannibal feast is the test — and it proves the charge against humanity.",
     ["lycaon"], "obj.lyc.test"),
   Q("q2", "What is Lycaon's punishment?",
     "Blasted by lightning and transformed into a wolf — his savagery made literal",
     ["Chained beneath the volcano", "Turned to stone mid-flight", "Drowned in the flood he caused"],
     "Ovid's justice: the inner beast becomes the outer form.", ["lycaon"], "obj.lyc.wolf")])

W('roman', 'day-03-venus', ["venus", "adonis", "anemone", "roman"],
  [{"id": "obj.ven.warning", "text": "What warning does Venus give Adonis?"},
   {"id": "obj.ven.flower", "text": "What does Adonis become?"}],
  [C(1, "The goddess who fell for a hunter", "Scratched by Cupid's arrow, Venus falls hopelessly for the mortal hunter Adonis — and abandons heaven to tramp the hills at his side, a goddess acting the huntress.", ["warning"], "obj.ven.warning"),
   C(2, "A lover's warning", "She warns him as she leaves: hunt only the timid creatures — never the fierce beasts that turn and fight. She even tells him Atalanta's story to make the lesson stick.", ["warning"], "obj.ven.warning"),
   C(3, "The wound that kills", "Adonis ignores her: his hounds rouse a wild boar, his spear only wounds it — and the boar gores him to death in the groin. The hunter dies as hunters die.", ["flower"], "obj.ven.flower"),
   C(4, "Blood into anemone", "Venus finds him dying and pours nectar on his blood: it swells and blooms into the anemone — the wind-flower, beautiful and as brief as the boy it remembers.", ["flower"], "obj.ven.flower"),
   C(5, "Love and loss, one poem", "Ovid's Adonis is the pattern of the whole book: desire and grief are the same story, and a flower is the shape mourning takes.", ["warning", "flower"], "obj.ven.flower", "context")],
  [Q("q1", "What warning does Venus give Adonis?",
     "Hunt only timid game — never the fierce beasts that turn to fight",
     ["Never hunt alone", "Never boast of his kills", "Never hunt at dawn"],
     "She warns him off the dangerous game — and he ignores it.", ["warning"], "obj.ven.warning"),
   Q("q2", "What does Adonis become at death?",
     "The anemone — the wind-flower sprung from his nectar-sprinkled blood",
     ["A stream where hunters drink", "The wild rose", "A star in Orion's belt"],
     "The brief anemone is his memorial — beauty as short-lived as he was.",
     ["flower"], "obj.ven.flower")])

W('roman', 'day-04-mars', ["mars", "romulus", "quirinus", "roman"],
  [{"id": "obj.mars.sons", "text": "Who are Mars's mortal children?"},
   {"id": "obj.mars.quirinus", "text": "What does Romulus become?"}],
  [C(1, "Rome's own father", "Mars is no distant war-god to the Romans: he is the literal father of Romulus and Remus, the twins who founded the city — the divine bloodline starts at the top.", ["request"], "obj.mars.sons"),
   C(2, "The god collects his son", "At Mars's own request, Jupiter takes up Romulus in a whirlwind and fire — the mortal king is dissolved from mortal substance and made divine.", ["request"], "obj.mars.quirinus"),
   C(3, "From king to Quirinus", "Ovid describes the change precisely: the mortal parts burn away, and what remains is the god Quirinus — Rome's founder made Rome's own deity.", ["change"], "obj.mars.quirinus"),
   C(4, "Why a deified founder matters", "For Romans this was state theology, not just story: Quirinus means the city has divine ancestry and a divine protector in one figure — mythic legitimation for the empire itself.", ["request", "change"], "obj.mars.quirinus"),
   C(5, "Rome writes its own myth", "Unlike Greece's remote heroes, Roman myth claims the gods are literally its founders and its emperors — and Ovid makes that political claim into verse.", ["request"], "obj.mars.sons", "context")],
  [Q("q1", "Who are Mars's twin sons?",
     "Romulus and Remus — the founders of Rome, making Mars the city's divine ancestor",
     ["Castor and Pollux", "Caesar and Augustus", "Numitor and Amulius"],
     "The twins make Mars Rome's founding father — literally.", ["request"], "obj.mars.sons"),
   Q("q2", "What does Romulus become at his end?",
     "The god Quirinus — taken up in fire at Mars's request, his mortal parts burned away",
     ["A star beside Mars", "The Tiber's river-god", "The first emperor of heaven"],
     "Rome's founder becomes Rome's own god — the city's divine protector.",
     ["request", "change"], "obj.mars.quirinus")])

W('roman', 'day-05-metamorphosis-reception', ["ovid", "caesar", "apotheosis", "roman"],
  [{"id": "obj.ovid.caesar", "text": "What does Caesar's soul become?"},
   {"id": "obj.ovid.immortal", "text": "What does Ovid claim for his poem?"}],
  [C(1, "The poem's closing boast", "Ovid ends the Metamorphoses by promising his work will outlast wrath, fire, and time: wherever Rome's power reaches, he will be read. A poet's own apotheosis.", ["plea"], "obj.ovid.immortal"),
   C(2, "Caesar's comet", "The book's last transformation is recent history: Julius Caesar's soul rises past the moon and blazes as a star — Rome's murdered ruler made divine in the sky.", ["star"], "obj.ovid.caesar"),
   C(3, "Augustus in the heavens", "Ovid then turns to Augustus: may HIS apotheosis be far in the future — flattery and prophecy in one gesture, addressed to the man who holds his fate.", ["plea"], "obj.ovid.immortal"),
   C(4, "Exile under the boast", "This ending was written under Augustus's displeasure — Ovid would die in exile at Tomis, and still he claimed the empire's ears.", ["plea"], "obj.ovid.immortal"),
   C(5, "A boast that came true", "He was right: the Metamorphoses became Europe's mythology textbook for two thousand years. The poet's apotheosis outlasted the emperor's.", ["star", "plea"], "obj.ovid.immortal", "flavor")],
  [Q("q1", "What does Julius Caesar's soul become?",
     "A blazing star — Rome's ruler made divine in the sky",
     ["A second sun", "The god of war", "A constellation of seven stars"],
     "Caesar's comet is the poem's last transformation — politics as apotheosis.",
     ["star"], "obj.ovid.caesar"),
   Q("q2", "What does Ovid claim for his poem at the end?",
     "That it will outlast fire, wrath, and time — read wherever Rome's power reaches",
     ["That the gods will forgive him", "That Augustus will restore him", "That only the stars outlast it"],
     "The poet claims his own immortality — and history proved him right.", ["plea"], "obj.ovid.immortal")])

# ===== CHINESE =====
W('chinese', 'day-01-heaven-earth', ["panku", "creation", "taoist", "chinese"],
  [{"id": "obj.pan.egg", "text": "How does P'an Ku make the world?"},
   {"id": "obj.pan.body", "text": "What does his body become?"}],
  [C(1, "The giant inside the egg", "In the Taoist account, Chaos was a cosmic egg — and inside it grew P'an Ku, who spent eighteen thousand years chiseling it apart: the light, pure parts rose as Heaven, the heavy parts sank as Earth.", ["creation"], "obj.pan.egg"),
   C(2, "Holding the sky apart", "Fearing the two would collapse back together, P'an Ku stands between them — pushing Heaven up and Earth down, growing taller every day for another eighteen thousand years until the separation holds.", ["creation"], "obj.pan.egg"),
   C(3, "The body that became the world", "When at last he dies, his breath becomes wind and clouds, his voice thunder, his left eye the sun and right eye the moon, his limbs the mountains, his blood the rivers, his hair the stars and plants.", ["origin"], "obj.pan.body"),
   C(4, "A creation made of a body", "Unlike a word-spoken creation, this cosmos is literally built out of one giant's body — the world as the remains of a sacrifice.", ["origin"], "obj.pan.body"),
   C(5, "A written-down folk story", "The account survives through later Chinese scholarship — a literary synthesis of what may be much older folk material. We hold the details at arm's length but the shape is real.", ["creation", "origin"], "obj.pan.egg", "context")],
  [Q("q1", "How does P'an Ku make Heaven and Earth?",
     "He chisels apart the cosmic egg for eighteen thousand years — the light parts rise, the heavy parts sink",
     ["He molds them from river clay", "He calls them into being with a word", "He carves them from a mountain"],
     "The egg's two halves become sky and ground — the oldest Chinese creation account.",
     ["creation"], "obj.pan.egg"),
   Q("q2", "What does P'an Ku's body become at death?",
     "The world's features — breath to wind, eyes to sun and moon, limbs to mountains, blood to rivers",
     ["A second cosmic egg", "The first humans", "The gods of the four directions"],
     "The cosmos is literally built from him — the world as his remains.", ["origin"], "obj.pan.body")])

W('chinese', 'day-02-nuwa-repair', ["nukua", "kungkung", "pillars", "chinese"],
  [{"id": "obj.nu.crack", "text": "What does Kung Kung do?"},
   {"id": "obj.nu.repair", "text": "How does Nu Kua repair the sky?"}],
  [C(1, "The sky cracks", "The rebel Kung Kung, defeated in a cosmic war, smashes his head against Mount Pu Chou — one of the pillars holding up the sky — and the heavens tilt, stars slip from place, and the earth tears open.", ["repair"], "obj.nu.crack"),
   C(2, "The goddess who mends the world", "Nu Kua melts down stones of five colours and patches the broken sky; she cuts the legs off a giant turtle and plants them as new pillars at the world's four corners, and stuffs the flood with reed-ashes.", ["repair"], "obj.nu.repair"),
   C(3, "A tilted sky that stayed tilted", "The repair was imperfect: ever since, the sky leans to the northwest — the myth explains why China's rivers flow southeast and the sun and moon roll that way across the sky.", ["repair"], "obj.nu.repair"),
   C(4, "Our window is Ssu-ma Cheng", "This version reaches us through the Tang scholar Ssu-ma Cheng's commentary on the Grand Historian's records — a medieval scholar preserving a much older myth for us.", ["repair"], "obj.nu.crack", "context"),
   C(5, "A creator who fixes", "Nu Kua is the opposite of a distant maker: she is a repairer, a god who stays close to the world she shaped and mends it when it breaks.", ["repair"], "obj.nu.repair", "flavor")],
  [Q("q1", "What does Kung Kung's rage do?",
     "He smashes Mount Pu Chou — a sky-pillar — and the heavens tilt and crack",
     ["He releases the ten suns", "He floods the Yellow River", "He steals the pillars of heaven"],
     "His headbutt cracks the sky — the damage Nu Kua must fix.", ["repair"], "obj.nu.crack"),
   Q("q2", "How does Nu Kua repair the heavens?",
     "She melts five-coloured stones to patch the sky and uses a giant turtle's legs as new pillars",
     ["She summons a dragon to hold it", "She weaves a new sky from silk", "She reforges the broken pillar"],
     "Patched sky, turtle-leg pillars — and a permanent tilt left over.", ["repair"], "obj.nu.repair")])

W('chinese', 'day-03-yu-flood', ["shenyi", "suns", "archer", "chinese"],
  [{"id": "obj.shen.crisis", "text": "What crisis scorches the earth?"},
   {"id": "obj.shen.suns", "text": "What does Shen I do about it?"}],
  [C(1, "Ten suns at once", "The ten suns — sons of the eastern god — all rise together one morning and scorch the world: crops wither, rivers dry, and monsters crawl out to feed on the people.", ["crisis"], "obj.shen.crisis"),
   C(2, "The archer sent down", "The emperor Yao begs heaven for help, and the divine archer Shen I is sent down with a red bow and white arrows — officially to frighten the suns back into order.", ["crisis"], "obj.shen.crisis"),
   C(3, "Nine arrows, nine suns", "Shen I goes further than ordered: he shoots nine suns out of the sky one by one — each falls to earth as a three-legged crow — and leaves the single sun we know.", ["suns"], "obj.shen.suns"),
   C(4, "The hero who went too far", "Saving the world gets Shen I exiled from heaven anyway: the gods resent a hero who acts beyond his orders. His mortality and his wife's fate follow from this demotion.", ["suns"], "obj.shen.suns"),
   C(5, "Through Werner's lens", "This account comes through E.T.C. Werner's 1922 English synthesis of Chinese myth — a retelling compilation, not a primary text, so we hold its details lightly.", ["crisis", "suns"], "obj.shen.crisis", "context")],
  [Q("q1", "What crisis scorches the earth?",
     "The ten suns rise together — crops wither, rivers dry, monsters come out to feed",
     ["A dragon swallows the rivers", "The sky-pillars fall", "An endless winter descends"],
     "Ten suns at once — the world burns before the archer acts.", ["crisis"], "obj.shen.crisis"),
   Q("q2", "What does Shen I do?",
     "He shoots nine of the ten suns — each falling as a three-legged crow — leaving one",
     ["He bargains the suns into taking turns", "He shades the earth with a mountain", "He moves the world away from them"],
     "Nine arrows, nine crows, one remaining sun.", ["suns"], "obj.shen.suns")])

W('chinese', 'day-04-change-moon', ["hengo", "moon", "elixir", "chinese"],
  [{"id": "obj.heng.pill", "text": "Why does Heng O swallow the elixir?"},
   {"id": "obj.heng.moon", "text": "Where does she end up?"}],
  [C(1, "The elixir of immortality", "For his service, the gods give the exiled archer Shen I a pill of eternal life — but he will not take it and leave his wife Heng O mortal. He locks it away instead.", ["flight"], "obj.heng.pill"),
   C(2, "The theft that forces her hand", "A thief breaks in to steal the pill. To keep it from him, Heng O swallows it herself — and instantly begins to rise from the earth.", ["flight"], "obj.heng.pill"),
   C(3, "To the moon", "She floats upward, past the reach of earth, and lands on the moon — where she becomes its resident spirit and, in some tellings, is changed into a toad.", ["moon"], "obj.heng.moon"),
   C(4, "The husband below", "Shen I is left behind, mortal and earthbound — their separation is marked at the Mid-Autumn Moon Festival, when moon-cakes are set out for her.", ["moon"], "obj.heng.moon"),
   C(5, "Why the moon has a lady", "Heng O is China's answer to the man in the moon: a figure visible from earth — eternally separated, eternally present, and loved from below.", ["flight", "moon"], "obj.heng.moon", "flavor")],
  [Q("q1", "Why does Heng O swallow the elixir?",
     "To keep it from a thief trying to steal it — and it carries her upward beyond return",
     ["She wants to join the gods", "She mistakes it for medicine", "Shen I commands her to"],
     "The theft forces the choice — immortality as an act of protection, not ambition.",
     ["flight"], "obj.heng.pill"),
   Q("q2", "Where does Heng O end up?",
     "On the moon — as its resident spirit, remembered at the Mid-Autumn Festival",
     ["On the sun beside her husband", "In the Western Paradise", "Transformed into a star"],
     "The moon is her exile and her shrine.", ["moon"], "obj.heng.moon")])

W('chinese', 'day-05-immortals-order', ["benevolent", "flood", "folktale", "chinese"],
  [{"id": "obj.ben.sign", "text": "What sign precedes the flood?"},
   {"id": "obj.ben.joke", "text": "What makes the sign come true?"}],
  [C(1, "A warning in a dream", "A good man is warned in a dream that a great flood is coming — and told to watch the city gate: when the iron statue's eyes bleed, he must flee to the hills.", ["warning"], "obj.ben.sign"),
   C(2, "The butcher's cruel joke", "A butcher hears of the man's daily watch and plays a trick: he smears blood on the statue's eyes. The man sees the 'sign' and runs for the hills.", ["warning"], "obj.ben.joke"),
   C(3, "The flood proves the warning", "And the flood comes — the joke became the prophecy. The warning was real even though the sign itself was faked.", ["warning", "rescue"], "obj.ben.joke"),
   C(4, "The widow and the turtle", "On the flood waters the man rescues a drowning widow — and a great turtle — and the turtle's later repayment turns the whole tale: kindness is the story's real engine.", ["rescue"], "obj.ben.joke"),
   C(5, "Macgowan's village tales", "This story comes through John Macgowan's 1910 collection of Chinese folk tales — a missionary's retelling of village stories, not a canonical scripture.", ["warning", "rescue"], "obj.ben.sign", "context")],
  [Q("q1", "What is the flood's prophesied sign?",
     "The iron statue at the city gate bleeding from its eyes",
     ["The river running backward", "A comet over the palace", "Three days of darkness"],
     "The bleeding statue is the signal to flee.", ["warning"], "obj.ben.sign"),
   Q("q2", "What makes the sign appear?",
     "The butcher's cruel joke — he smears blood on the statue's eyes, and the flood follows anyway",
     ["The man bleeds on it himself", "The statue weeps at the city's sins", "An earthquake cracks it open"],
     "The faked sign doesn't make the warning false — the flood proves it true.",
     ["warning"], "obj.ben.joke")])

# ===== MESOAMERICAN =====
W('mesoamerican', 'day-01-five-suns', ["nanahuatl", "fifth-sun", "sacrifice", "mesoamerican"],
  [{"id": "obj.nan.fire", "text": "How does Nanahuatl become the sun?"},
   {"id": "obj.nan.rabbit", "text": "Why does the moon have a rabbit?"}],
  [C(1, "A world in darkness", "Before the sun, humanity lives in darkness. The gods gather at Teotihuacan to choose who will be sacrificed to become the new sun.", ["sun"], "obj.nan.fire"),
   C(2, "The boast and the humility", "The proud, rich god Tecciztecatl volunteers loudly for the honour; the humble, pockmarked Nanahuatl — covered in sores — is chosen but stays silent.", ["sun"], "obj.nan.fire"),
   C(3, "The leap into the fire", "At the great pyre, Tecciztecatl falters at the flames again and again; Nanahuatl leaps in at once — and rises as the sun. Ashamed, Tecciztecatl follows and becomes the moon.", ["sun"], "obj.nan.fire"),
   C(4, "The dimming of the second light", "The second sun blazes too brightly to be night — so the gods hurl a rabbit at it to dim it. That is why the moon carries a rabbit on its face.", ["sun"], "obj.nan.rabbit"),
   C(5, "The fifth sun needs feeding", "This is the fifth sun: four previous worlds ended in destruction. The Mexica read this as a debt — the sun stays in motion only through sacrifice.", ["sun"], "obj.nan.fire", "context")],
  [Q("q1", "How does Nanahuatl become the sun?",
     "He leaps into the pyre without hesitating, while the proud Tecciztecatl falters at the flames",
     ["He is thrown in by the other gods", "He defeats the moon-god in combat", "He is born already burning"],
     "The humble god leaps first — and becomes the greater light.", ["sun"], "obj.nan.fire"),
   Q("q2", "Why does the moon have a rabbit on it?",
     "The gods hurled a rabbit at the second sun to dim it — its mark stays on the moon",
     ["It is Nanahuatl's companion", "The rabbit is the moon's true form", "It marks where Tecciztecatl hid"],
     "The dimmed second sun keeps the rabbit's print.", ["sun"], "obj.nan.rabbit")])

W('mesoamerican', 'day-02-quetzalcoatl', ["quetzalcoatl", "tollan", "departure", "mesoamerican"],
  [{"id": "obj.quet.king", "text": "Who was Quetzalcoatl at Tollan?"},
   {"id": "obj.quet.leave", "text": "How does he depart?"}],
  [C(1, "The feathered serpent as king", "In one strand of the tradition, Quetzalcoatl — the Feathered Serpent — was the priest-king of the Toltec city of Tollan: a wise ruler who taught crafts and opposed human sacrifice.", ["departure"], "obj.quet.king"),
   C(2, "Tricked by the sorcerer", "The dark sorcerer Tezcatlipoca, his rival, tricks him into drunkenness and shame — the disgraced king can no longer hold his city.", ["departure"], "obj.quet.king"),
   C(3, "The raft of serpents", "At the eastern shore he departs on a raft of serpents, promising to return — the famous eastward exit into myth.", ["departure"], "obj.quet.leave"),
   C(4, "The myth that met the sea", "Centuries later the story would be told of the Mexica looking east for a returning god when strangers landed — one of history's most contested claims.", ["departure"], "obj.quet.leave"),
   C(5, "A Toltec inheritance", "The tale reached the Mexica through Toltec prestige — one people's god-king became another's omen, and the line between legend and later propaganda stays blurry.", ["departure"], "obj.quet.king", "context")],
  [Q("q1", "Who was Quetzalcoatl at Tollan?",
     "A wise Toltec priest-king — teacher of crafts, opponent of human sacrifice",
     ["A conquering war-god", "The first emperor of Mexico", "A god of the dead"],
     "The feathered serpent as civilizing king — the Toltec face of the god.", ["departure"], "obj.quet.king"),
   Q("q2", "How does Quetzalcoatl leave Tollan?",
     "Tricked into disgrace by Tezcatlipoca, he sails east on a raft of serpents, promising to return",
     ["He burns himself and becomes Venus", "He is exiled by the priests", "He walks into the underworld"],
     "The serpent-raft departure — and the promise of return — is the famous exit.", ["departure"], "obj.quet.leave")])

W('mesoamerican', 'day-03-huitzilopochtli', ["huitzilopochtli", "coatepec", "coyolxauhqui", "mesoamerican"],
  [{"id": "obj.huit.birth", "text": "How is Huitzilopochtli born?"},
   {"id": "obj.huit.battle", "text": "Who does he defeat?"}],
  [C(1, "A miraculous pregnancy", "At Coatepec hill, the mother-goddess Coatlicue is sweeping the shrine when a ball of feathers falls from the sky; she tucks it into her bosom and becomes pregnant — to the fury of her daughter Coyolxauhqui and her four hundred sons.", ["birth"], "obj.huit.birth"),
   C(2, "Born fully armed", "As the siblings march up the hill to kill their mother for the disgrace, Huitzilopochtli is born fully grown and armed — hummingbird feathers, shield, and the fire-serpent Xiuhcoatl in his hand.", ["birth"], "obj.huit.birth"),
   C(3, "The moon's defeat", "He strikes Coyolxauhqui and sends her tumbling down the hill in pieces — the Mexica read her dismemberment in the moon's phases, and the four hundred brothers became the stars.", ["battle"], "obj.huit.battle"),
   C(4, "A war god's charter", "The myth is a charter: Huitzilopochtli is born fighting, the sun to his sister's moon — the patron of a people who built an empire on war.", ["battle"], "obj.huit.battle"),
   C(5, "Theology at the capital", "At Tenochtitlan's Templo Mayor, the offerings to Huitzilopochtli faced Coyolxauhqui's great carved stone at the pyramid's foot — the myth was built into the city itself.", ["birth", "battle"], "obj.huit.battle", "context")],
  [Q("q1", "How is Huitzilopochtli born?",
     "Fully grown and armed — hummingbird feathers and the fire-serpent — to defend his mother",
     ["As an egg that hatches in war", "From the sun's own rays", "A child who grows overnight"],
     "Born fighting — the war god's whole nature in his first minute.", ["birth"], "obj.huit.birth"),
   Q("q2", "Who does Huitzilopochtli defeat at Coatepec?",
     "His sister Coyolxauhqui and the four hundred brothers — read as the moon and the stars",
     ["The giant of the mountain", "Tezcatlipoca's army", "The lords of Mictlan"],
     "His victory sets sun over moon and stars — astronomy as family war.", ["battle"], "obj.huit.battle")])

W('mesoamerican', 'day-04-underworld-road', ["mictlan", "death", "xolo", "mesoamerican"],
  [{"id": "obj.mic.journey", "text": "How do the dead reach Mictlan?"},
   {"id": "obj.mic.dog", "text": "What helps them cross the river?"}],
  [C(1, "The four-year road", "For the Mexica, most dead went to Mictlan — a nine-level underworld reached by a four-year journey downward. It is not a judgment: nearly everyone takes the road.", ["journey"], "obj.mic.journey"),
   C(2, "The dog that ferries", "At the first river, the soul needs a red dog — the xoloitzcuintli — to carry it across. That is why dogs were buried with the dead: the ferryman is waiting.", ["journey"], "obj.mic.dog"),
   C(3, "Nine trials down", "The soul passes clashing mountains, a wind of knives, rivers and deserts — each level stripping away another layer of attachment to the world above.", ["journey"], "obj.mic.journey"),
   C(4, "The lord of death's palace", "At the deepest level, Mictlantecuhtli, lord of the dead, receives the soul into final rest — an extinction more than a paradise or a punishment.", ["journey"], "obj.mic.journey"),
   C(5, "A different moral map", "Unlike the Greek judgment hall, Mictlan is not earned — it is a process every ordinary soul walks. In this cosmos, how you die matters more than how you lived.", ["journey"], "obj.mic.journey", "context")],
  [Q("q1", "How do the dead reach Mictlan?",
     "A four-year journey down through nine levels — clashing mountains, knife-winds, rivers, deserts",
     ["They are carried by the sun's rays", "A single night of travel", "Through the fire that took them"],
     "The road is long and takes years — the underworld is a pilgrimage, not a doorway.", ["journey"], "obj.mic.journey"),
   Q("q2", "What helps the soul cross the river?",
     "A red dog — the xoloitzcuintli — buried with them for exactly this purpose",
     ["A silver coin under the tongue", "The prayers of the living", "A feathered boatman"],
     "The buried dog is the ferryman — hence dogs in the graves.", ["journey"], "obj.mic.dog")])

W('mesoamerican', 'day-05-sacred-obligation', ["mexica", "omen", "tenochtitlan", "mesoamerican"],
  [{"id": "obj.mex.sign", "text": "What is the foundation omen?"},
   {"id": "obj.mex.lake", "text": "Why does the city rise on a lake?"}],
  [C(1, "Wandering for a sign", "The Mexica wander for generations, driven from place to place, carrying a prophecy: where you see an eagle perched on a cactus devouring a serpent, there build your city.", ["omen"], "obj.mex.sign"),
   C(2, "The lake nobody wanted", "When priests finally see the sign, it is on a tiny island in Lake Texcoco — land the valley's powers had already written off as worthless.", ["omen"], "obj.mex.lake"),
   C(3, "A city built on water", "They build Tenochtitlan in the lake itself: canals for streets, causeways for roads, floating chinampa gardens feeding the people — a Venice of the Americas.", ["omen"], "obj.mex.lake"),
   C(4, "The sign on a flag", "The eagle on the cactus is on Mexico's flag today — a prophecy that became a founding image and then a national symbol.", ["omen"], "obj.mex.sign"),
   C(5, "A Nahua charter myth", "This is a Mexica (one Nahua people) charter story: the sign legitimizes their right to rule the valley — prophecy as a deed of ownership.", ["omen"], "obj.mex.sign", "context")],
  [Q("q1", "What is the Mexica foundation omen?",
     "An eagle perched on a cactus devouring a serpent — the sign for where to build",
     ["A hummingbird over the lake", "A jaguar on a temple stone", "The sun rising through a pyramid"],
     "The eagle-and-serpent is the image on Mexico's flag today.", ["omen"], "obj.mex.sign"),
   Q("q2", "Why is Tenochtitlan built on a lake?",
     "The sign appeared on a lake island — land the powerful had rejected — so they built on water",
     ["The lake was sacred to Huitzilopochtli", "They were driven there by enemies", "The lake promised better fishing"],
     "The prophecy made the worthless land the chosen place.", ["omen"], "obj.mex.lake")])

